import React from 'react';

export default function ThreeSixtyViewer({ url, onClose }) {
  if (!url) return null;

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.8)', zIndex: 1080 }}>
      <div className="modal-dialog modal-fullscreen">
        <div className="modal-content bg-transparent border-0">
          <div className="modal-header border-0 position-absolute top-0 end-0" style={{ zIndex: 2 }}>
            <button type="button" className="btn-close btn-close-white" onClick={onClose}></button>
          </div>
          <div className="modal-body p-0 d-flex align-items-center justify-content-center text-white">
            {/* 
              In a real application, you would integrate a 360 viewer library here.
              Example using Pannellum:
              import { Pannellum } from "pannellum-react";
              <Pannellum width="100%" height="100%" image={url} pitch={10} yaw={180} hfov={110} autoLoad />
            */}
            <div className="text-center">
              <h3>🔄 عارض الجولات الافتراضية 360°</h3>
              <p>هنا يتم عرض الجولة الافتراضية للعقار.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
